package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.Locale;
import java.util.stream.Collectors;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a due, {@code statedDue} (null: n/a) — its due as shown then, late
 * charge and floor included; it then shows and totals that due, not its live one. {@code number} is sheet-wide (1, 2, ...) or, under period numbering,
 * within its period (P1-1, X-1). {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction). {@code dueBy} is fixed when the claim is created: the terms-th business day after its date (skipping Saturdays,
 * Sundays and the sheet's holidays) for its person's own terms, else those of their grade, else the sheet's, each in
 * force on that date; it does not change when the terms or its date change later. A PENDING claim is bound like any other claim that counts: while a statement binds it, it shows and
 * totals the bound figure. {@code deferredUntil} is the date an OPEN claim is
 * deferred until (null: never deferred): while the sheet's today is before it the claim is {@link #deferred deferred}.
 * {@code proofs} is how many proofs the claim has been given. {@code splitFrom} is the number of the claim it was split
 * off (null: not split off another claim). {@code added} is when the claim was added to the sheet, on the sequence rates
 * are saved on (see {@link net.officefloor.hq.app.rate.Rate#appliesTo}): a forward-only rate applies only to claims added
 * after it was saved; {@link #NEWEST} for a claim not yet stored. {@code waived} is whether a steward waived its late
 * charge: a waived claim bears no late charge, whatever its overdue state. {@code held} is whether the claim is held:
 * a held OPEN or PENDING claim leaves the live totals as a hold on its person would (unless a statement binds it).
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom, long added,
        boolean waived, boolean held) {

    /** The {@code added} of a claim not yet stored: added after every rate. */
    public static final long NEWEST = Long.MAX_VALUE;

    /** A claim that is not held. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom, long added,
            boolean waived) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, splitFrom, added, waived, false);
    }

    /** A claim whose late charge is not waived. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom, long added) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, splitFrom, added, false);
    }

    /** A claim not yet stored. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, splitFrom, NEWEST);
    }

    /** A claim not split off another claim. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, null);
    }

    /** A claim with no proofs. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, 0);
    }

    /** A claim never deferred. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, null);
    }

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, String nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, added, waived, held);
    }

    /** The same claim as an open claim bound by no statement: live, with no fixed due. */
    public Claim asOpenUnbound() {
        return new Claim(id, sheetId, personId, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false,
                null, corrects, dueBy, deferredUntil, proofs, splitFrom, added, waived, held);
    }

    /**
     * The claim keeping the rest of its amount once the split amount goes to a new claim: it loses any figure a
     * statement bound it to.
     */
    public Claim splitKeeping(BigDecimal rest) {
        return new Claim(id, sheetId, personId, rest, date, note, status, number, due, openedBy, false, null,
                corrects, dueBy, deferredUntil, proofs, splitFrom, added, waived, held);
    }

    /** Whether the claim is a correction: a negative amount naming the settled claim it corrects. */
    public boolean correction() {
        return corrects != null;
    }

    /** Whether the claim counts toward the totals: only OPEN, PENDING and SETTLED claims do. */
    public boolean counts() {
        return status.open() || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when a hold on its person covers it or not: a held open (or pending) claim does not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status.open() && !held);
    }

    /**
     * Whether the claim is deferred on the given today: OPEN (or SETTLED while a statement bound it), deferred until a
     * date after that day, and bound by no statement. A deferred claim counts in no total, is not overdue, cannot be
     * settled and is left unbound by a statement; a claim deferred while bound stays in the totals and can be settled
     * until the binding ends (the statement is cancelled, or the next one leaves it unbound).
     */
    public boolean deferred(LocalDate today) {
        return (status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED) && !bound() && deferredUntil != null
                && today != null && today.isBefore(deferredUntil);
    }

    /** The same claim deferred until the date. */
    public Claim deferTo(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, until, proofs, splitFrom, added, waived, held);
    }

    /** The same claim on another date with the given number, keeping its due-by and any statement figure. */
    public Claim redateTo(LocalDate nextDate, String nextNumber) {
        return new Claim(id, sheetId, personId, amount, nextDate, note, status, nextNumber, due, openedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, added, waived, held);
    }

    /** The same claim with one more proof. */
    public Claim withProof() {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, deferredUntil, proofs + 1, splitFrom, added, waived, held);
    }

    /** Whether a proof can be added to the claim: it is neither SETTLED, VOID nor DELETED. */
    public boolean takesProof() {
        return status != ClaimStatus.SETTLED && status != ClaimStatus.VOID && status != ClaimStatus.DELETED;
    }

    /** Whether the claim is overdue on the given today: OPEN (or PENDING), not deferred, with its due-by before that day. */
    public boolean overdue(LocalDate today) {
        return overdue(today, 0);
    }

    /** Whether the claim is overdue on the given today with the grace days: its due-by plus them before that day. */
    public boolean overdue(LocalDate today, int grace) {
        return status.open() && !deferred(today) && dueBy != null && today != null
                && dueBy.plusDays(grace).isBefore(today);
    }

    /** Whether a statement binds the claim now: it was stated (PENDING included). */
    public boolean bound() {
        return stated;
    }

    /** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
    public boolean keepsFigure() {
        return due != null || (bound() && statedDue != null);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the due its statement bound
     * it to, else its amount at the given live rate (null: none) — no floor. Its live figure
     * rounds by the sheet's policy date.
     */
    public BigDecimal figure(BigDecimal liveRate, Rounding rounding) {
        if (due != null) {
            return due;
        }
        if (bound()) {
            return statedDue;
        }
        return due(amount, liveRate, rounding.modeFor(this));
    }

    /**
     * The claim's due (null: n/a): the due fixed when it was settled, else the due its statement bound it to, else
     * the greater of the floor in force on its date and its {@link #figure figure}, plus the late charge on that
     * floored figure while it is overdue. A settled claim's fixed due and a bound due already have the charge and floor in them; a
     * correction has no floor and no charge.
     */
    public BigDecimal due(BigDecimal liveRate, BigDecimal floor, LateCharge late, Rounding rounding) {
        BigDecimal figure = figure(liveRate, rounding);
        if (due != null || bound() || figure == null || correction()) {
            return figure;
        }
        BigDecimal floored = atLeast(figure, floor);
        return floored.add(late.on(this, floored, rounding.modeFor(this)));
    }

    /** An amount times a percent rate, divided by 100, rounded by the mode to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, RoundingMode mode) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, mode);
    }

    /** The value raised to the floor (null: no floor). */
    static BigDecimal atLeast(BigDecimal value, BigDecimal floor) {
        return floor == null || value.compareTo(floor) >= 0 ? value : floor.setScale(2);
    }

    /** The audit field for a claim's external reference, " ref=<reference>", or "" when it has none. */
    public static String auditRef(String ref) {
        return ref == null ? "" : " ref=" + ref;
    }

    /**
     * Tags as typed (comma separated) in their stored form: each trimmed and lower-cased, blanks and repeats dropped,
     * sorted and comma separated; null when there are none.
     */
    public static String tags(String typed) {
        if (typed == null) {
            return null;
        }
        String tags = Arrays.stream(typed.split(",")).map((t) -> t.strip().toLowerCase(Locale.ROOT))
                .filter((t) -> !t.isEmpty()).distinct().sorted().collect(Collectors.joining(","));
        return tags.isEmpty() ? null : tags;
    }

    /** The audit field for a claim's tags, " tags=<a,b>", or "" when it has none. */
    public static String auditTags(String tags) {
        return tags == null ? "" : " tags=" + tags;
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 * the number null unless it has one, the due fixed at settling (two decimals) or null while it is live,
 * the user who opened it or null while it is a draft, whether a statement bound it and the figure it bound
 * it to (two decimals; null: n/a), and the number of the claim a correction corrects (null: not a correction), and its due-by fixed when it was created (yyyy-MM-dd), and its status log, oldest first, and the date it is deferred until (yyyy-MM-dd; null: never deferred), and how many proofs it has been given, and the number of the claim it was split off (null: none), and the user whose open editor locks it (null: not locked), and whether it is a late entry (added while its period was soft-closed), and the last day it was reminded (yyyy-MM-dd; null: never), and its external reference (null: none), and its tags, sorted (none: empty), and the reason it was voided with (null: none), and its comments, oldest first, and the number of the bulk settle batch that settled it (null: none), and its lines, in the order added, and when it was added (on the sequence rates are saved on: see the rate's saved), and whether its late charge was waived, and how many of its proofs are of each kind (receipt, photo), and whether it is held, and the people it is shared with and their shares (two decimals), in the order given, and the user its review is assigned to (null: none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<LogLine> log, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String reminded, String ref, List<String> tags, String voidReason,
        List<Comment> comments, Integer batch, List<Line> lines, long added, boolean waived, Map<String, Integer> proofKinds, boolean held,
        List<Share> shares, String reviewAssigned) {

    /** A line of the status log: the status, the user who gave it, the sheet's today then and the due then. */
    public record LogLine(String status, String by, String date, String due) {
    }

    /** A comment: the user who wrote it, the sheet's today then and its text. */
    public record Comment(String by, String date, String text) {
    }

    /** A line: its label, its quantity and its unit amount (two decimals). */
    public record Line(String label, int qty, String unit) {
    }

    /** A share: the id of the person holding it and the percent they hold (two decimals). */
    public record Share(long personId, String share) {
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log) {
        return from(claim, log, null, false, null, null, null, null, List.of(), null, List.of(), 0, List.of(), null);
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log, String lockedBy, boolean lateEntry,
            LocalDate reminded, String ref, String tags, String voidReason, List<ClaimComment> comments,
            Integer batch, List<ClaimLine> lines, int photoProofs, List<ClaimShare> shares,
            String reviewAssigned) {
        Map<String, Integer> proofKinds = new LinkedHashMap<>();
        proofKinds.put(ProofKind.RECEIPT, claim.proofs() - photoProofs);
        proofKinds.put(ProofKind.PHOTO, photoProofs);
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().setScale(2).toPlainString(), claim.openedBy(),
                claim.stated(), claim.statedDue() == null ? null : claim.statedDue().setScale(2).toPlainString(),
                claim.corrects(), claim.dueBy().toString(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(),
                claim.proofs(), claim.splitFrom(), lockedBy, lateEntry,
                reminded == null ? null : reminded.toString(), ref,
                tags == null ? List.of() : List.of(tags.split(",")), voidReason,
                comments.stream().map((c) -> new Comment(c.by(), c.date().toString(), c.text())).toList(), batch,
                lines.stream().map((l) -> new Line(l.label(), l.qty(), l.unit().setScale(2).toPlainString())).toList(),
                claim.added(), claim.waived(), proofKinds, claim.held(),
                shares.stream().map((s) -> new Share(s.personId(), s.share().setScale(2).toPlainString())).toList(),
                reviewAssigned);
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * How a claim's live figures (the rate step and the late charge) are rounded: a claim dated before the sheet's
 * policy date rounds half up, one dated on or after it half to even — unless a rounding mode is in force on its date
 * ({@code modes}: the mode in force on a date, null: none), which it rounds by instead. A correction rounds by the date
 * of the claim it corrects, not its own; {@code dates} holds the claims' dates by number.
 */
public record Rounding(LocalDate policyDate, Map<String, LocalDate> dates, Function<LocalDate, RoundingMode> modes) {

    /** The rounding by the policy date for the given claims (those a correction may name), with no rounding mode. */
    public static Rounding of(LocalDate policyDate, List<Claim> claims) {
        return of(policyDate, (date) -> null, claims);
    }

    /** The rounding by the rounding mode in force on a claim's date, else by the policy date, for the given claims. */
    public static Rounding of(LocalDate policyDate, Function<LocalDate, RoundingMode> modes, List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim claim : claims) {
            if (claim.number() != null) {
                dates.put(claim.number(), claim.date());
            }
        }
        return new Rounding(policyDate, dates, modes);
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate dateOf(Claim claim) {
        return claim.correction() ? dates.getOrDefault(claim.corrects(), claim.date()) : claim.date();
    }

    /** How the claim's live figures round. */
    public RoundingMode modeFor(Claim claim) {
        LocalDate date = dateOf(claim);
        RoundingMode mode = modes.apply(date);
        if (mode != null) {
            return mode;
        }
        return date.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.Function;

/**
 * What an overdue claim is charged: for every full 30 days it is overdue (its due-by, fixed when it was created, plus
 * the grace days of its person's grade in force on its date, before the sheet's today), the late percent in force on
 * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days) of its figure plus the charges of the
 * boundaries before it (compounding), rounded like the claim's due, the charges added up; a boundary whose percent is 0.00 adds nothing. It follows the
 * sheet's today until the claim is settled, or while a statement binds the claim's due (charge included). A correction, a deferred claim and a claim whose
 * charge was waived is never charged.
 */
public record LateCharge(Function<LocalDate, BigDecimal> pctOn, Function<Claim, Integer> graceOf, LocalDate today) {

    /** A charge with no grace days for any claim. */
    public LateCharge(Function<LocalDate, BigDecimal> pctOn, LocalDate today) {
        this(pctOn, (claim) -> 0, today);
    }

    /** The days in each period an overdue claim is charged for. */
    public static final int PERIOD_DAYS = 30;

    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.status().open() || claim.deferred(today) || claim.correction() || claim.waived()) {
            return charge;
        }
        LocalDate lateFrom = claim.dueBy().plusDays(graceOf.apply(claim));
        long late = ChronoUnit.DAYS.between(lateFrom, today);
        long periods = late > 0 ? late / PERIOD_DAYS : 0;
        for (long period = 1; period <= periods; period++) {
            BigDecimal pct = pctOn.apply(lateFrom.plusDays(period * PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(Claim.due(figure.add(charge), pct, mode));
            }
        }
        return charge;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * A claim's due as the screen shows it at this moment (null: n/a): its fixed due, else the greater of the sheet's floor
 * in force on its date and its figure — at its person's grade's rate in force on its date, rounded by its policy date, or
 * the figure a statement bound it to — plus the late charge (at the late percent in force on each 30-day boundary) it has
 * on the sheet's today, if overdue.
 */
public final class ClaimDueNow {

    private ClaimDueNow() {
    }

    public static BigDecimal of(Claim claim, SheetRepository sheets, PersonRepository people, RateRepository rates,
            SettingRepository settings, ClaimRepository claims) {
        Person person = people.find(claim.sheetId(), claim.personId());
        BigDecimal rate = person == null ? null
                : Rate.inForce(rates.findAll(claim.sheetId()), person.gradeOn(claim.date()), claim);
        LocalDate today = sheets.today(claim.sheetId());
        DatedSettings dated = settings.dated(claim.sheetId());
        return claim.due(rate, dated.floorOn(claim.date()), dated.lateCharge(today, person),
                settings.rounding(claim.sheetId(), today, claims.findForPerson(claim.sheetId(), claim.personId())));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The numbers claims are given on their sheet. */
public final class ClaimNumbers {

    private ClaimNumbers() {
    }

    /**
     * The number opening the claim gives it now: FY&lt;year&gt;-&lt;n&gt;, the tree's next within the fiscal year its
     * due-by falls in (named by the year it starts in), or the next within its period under period numbering.
     */
    public static String next(Claim claim, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods) {
        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
            int year = fiscalYear(claim.dueBy(), settings.fiscalStartMonth(claim.sheetId()));
            return "FY" + year + "-" + sheets.nextFiscalClaimNumber(claim.sheetId(), year);
        }
        Period period = periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(claim.dueBy())).findFirst()
                .orElse(null);
        String prefix = period == null ? "X" : period.name();
        String key = period == null ? "" : period.name().toLowerCase();
        return prefix + "-" + sheets.nextPeriodClaimNumber(claim.sheetId(), key);
    }

    /** The fiscal year a date falls in, named by the calendar year it starts in. */
    static int fiscalYear(LocalDate date, int startMonth) {
        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import org.springframework.stereotype.Component;

/**
 * Marks a claim just added a late entry when the period containing its due-by is soft-closed, recorded as LATE_ENTRY
 * (after its CLAIM_ADDED); nothing otherwise. Used by the claim form, the quick-add and the paste.
 */
@Component
public class LateEntries {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final Audit audit;

    public LateEntries(PeriodRepository periods, ClaimRepository claims, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.audit = audit;
    }

    public void mark(Claim claim, Person person, String user) {
        if (periods.softClosedOn(claim.sheetId(), claim.dueBy()) == null) {
            return;
        }
        claims.markLateEntry(claim);
        audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The due-by a claim of the person on the date is fixed with when it is created: the terms-th business day after its
 * date — skipping Saturdays, Sundays and the sheet's holidays (as the list stands now) — for the person's own terms,
 * else those of the grade they had, else the sheet's, each as in force on the day it is created (the sheet's today). */
public final class NewDueBy {

    private NewDueBy() {
    }

    public static LocalDate of(LocalDate date, Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date,
