import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { bound, counts } from '../claims/claims';
import type { Claim, ClaimShare } from '../claims/claims';
import { lateBoundary, latePeriods } from '../overdue/dueBy';
import { gradeOn, liveHolds } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';
import { claimGrace } from '../settings/settings';
import type { DueRules } from '../settings/settings';

/**
 * A grade's rate as the store holds it: a percent with two decimals, in force from its from-date
 * (yyyy-MM-dd; null: from the beginning of time) until the grade's next rate takes over, or through its
 * to-date (null: no end), whichever comes first. `sheet` is the sheet it is set on: the sheet's own rates come
 * first, then those it inherits from its parent, its parent's parent and so on (up to three levels up), then, for a
 * cloned sheet, those of the sheet it was cloned from (with its own parents and source likewise). A rate is kept
 * as versions, one per time it was set for its grade and from-date: this is the newest (in force), `version` how many.
 * A rate saved with a from-date on or after the sheet's today is `forward`-only: it applies only to claims added after
 * it was `saved` (a claim's `added` is on the same sequence); a claim added before keeps the `earlier` version that
 * applied to it (null: none).
 */
export type Rate = {
  grade: string;
  rate: string;
  from: string | null;
  to: string | null;
  sheet: string;
  version: number;
  forward?: boolean;
  saved?: number;
  earlier?: Rate | null;
};

/** The fields the rate form submits; a blank from-date is from the beginning of time, a blank to-date no end. */
export type RateInput = { grade: string; rate: string; from: string; to: string };

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

/** 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's rates; under sheetKey, so re-loading the sheet re-reads them. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;

/** The sheet's rates, by grade and then from-date (from the start first), then those it inherits, nearest parent first, then the clone source's. */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: !!sheet,
  });
}

/**
 * The grade's rate (two decimals) in force on the date: the one with the latest from-date on or
 * before it, a rate with no from-date applying from the start; undefined when none applies, or when that
 * one's to-date is before the date. With inherited rates, the first sheet (own, then the nearest parent up, then the clone source) with
 * a rate in force gives it.
 */
export function rateFor(rates: Rate[], grade: string | undefined, date: string): string | undefined {
  const sheets = [...new Set(rates.map((r) => r.sheet))];
  for (const sheet of sheets) {
    const rate = ownRateFor(rates.filter((r) => r.sheet === sheet), grade, date);
    if (rate !== undefined) return rate;
  }
  return undefined;
}

/** The grade's rate in force on the date among one sheet's rates, as {@link rateFor}. */
function ownRateFor(rates: Rate[], grade: string | undefined, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < date) return undefined;
  return found?.rate;
}

/** The newest version of the rate that applies to a claim added at `added`; undefined with none. */
function versionFor(rate: Rate, added: number): Rate | undefined {
  let version: Rate | null | undefined = rate;
  while (version && version.forward && added <= (version.saved ?? 0)) version = version.earlier;
  return version ?? undefined;
}

/** The rates as they apply to the claim: each at the newest version that applies to it, those with none left out. */
export function ratesForClaim(rates: Rate[], claim: Claim): Rate[] {
  return rates.map((r) => versionFor(r, claim.added ?? Number.MAX_SAFE_INTEGER)).filter((r): r is Rate => !!r);
}

/** A two-decimal value as whole hundredths, exactly. */
const hundredths = (value: string) => Math.round(Number(value) * 100);

/** How a half is rounded: half up (away from zero) or half to even. */
export type Rounding = 'half-up' | 'half-even';

/**
 * How a claim's live figures round: by the rounding mode in force on its date; with none, half up when it is
 * dated before the sheet's policy date, half to even on or after it. A correction rounds by the date of the
 * claim it corrects, not its own.
 */
export function roundingFor(claim: Claim, rules: DueRules): Rounding {
  const date = claim.corrects !== null ? (rules.claimDates.get(claim.corrects) ?? claim.date) : claim.date;
  const mode = rules.roundingOn(date);
  if (mode === 'half-up' || mode === 'half-even') return mode;
  return date < rules.policyDate ? 'half-up' : 'half-even';
}

/**
 * An amount times a percent rate, divided by 100, rounded to two decimals (half to even unless told
 * otherwise); n/a with no rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined, rounding: Rounding = 'half-even'): string {
  if (rate === undefined) return NA;
  return percentOf(hundredths(amount), hundredths(rate), rounding);
}

/** Cents times basis points / 10000, rounded to two decimals as told. */
function percentOf(amountCents: number, basisPoints: number, rounding: Rounding): string {
  const product = amountCents * basisPoints;
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && (rounding === 'half-up' || whole % 2 === 1));
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}

/** A due raised to the floor (both two decimals); n/a stays n/a. */
export function floored(value: string, floor: string): string {
  return value !== NA && hundredths(value) < hundredths(floor) ? Number(floor).toFixed(2) : value;
}

/**
 * A claim's figure: the due its statement bound it to, else its amount at the rate in force on its
 * date for the person's grade in force on that date (of the rate versions that apply to it), rounded by the policy
 * date — no floor.
 */
function claimFigure(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (bound(claim)) return claim.statedDue ?? NA;
  const rate = rateFor(ratesForClaim(rates, claim), gradeOn(grades, claim.date), claim.date);
  return due(claim.amount, rate, roundingFor(claim, rules));
}

/**
 * The late charge on a figure, compounded: for every full 30 days the claim is overdue, the late percent in force on that
 * boundary date (its due-by plus the grace days of its person's grade on its date plus 30, 60, 90 ... days) of the figure
 * plus the charges of the boundaries before it, rounded like the claim's due, the charges added up (a boundary at 0.00
 * adds nothing); 0.00 when it is not overdue, and always for a correction or a claim whose charge was waived.
 */
export function lateCharge(claim: Claim, figure: string, grades: GradeFrom[], rules: DueRules): string {
  if (claim.corrects !== null || claim.waived) return '0.00';
  const grace = claimGrace(claim, grades, rules);
  const periods = latePeriods(claim, rules.today, grace);
  const charges: string[] = [];
  for (let period = 1; period <= periods; period++) {
    const pct = hundredths(rules.latePctOn(lateBoundary(claim, period, grace)));
    if (pct !== 0) charges.push(percentOf(hundredths(total([figure, ...charges])), pct, roundingFor(claim, rules)));
  }
  return total(charges);
}

/**
 * A claim's due: the one fixed when it was settled (any late charge and floor frozen in), else the due its
 * statement bound it to (late charge and floor included, as shown when it was taken), else the greater of the floor in
 * force on its date and its figure, plus the late charge on that floored figure while it is overdue — a correction has no floor and no
 * charge.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules);
  if (figure === NA || bound(claim) || claim.corrects !== null) return figure;
  const raised = floored(figure, rules.floorOn(claim.date));
  return total([raised, lateCharge(claim, raised, grades, rules)]);
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (bound(c) && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. Their open claims a hold covers (not bound by a statement) do not count. With `shared`, shared claims are
 * parted between their own person and their holders. The cap in force on the date of their latest claim that counts covers it plus their cut total: it is at most
 * the cap less their cut total, not below 0.00 (n/a is not capped).
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
  shared?: Shared,
): string {
  const sum = personSum(claims, rates, grades, holds, rules, shared);
  const cap = personCap(claims, holds, rules);
  if (sum === NA || cap === '') return sum;
  const room = Math.max(0, hundredths(cap) - personCut(rules, shared));
  return hundredths(sum) <= room ? sum : (room / 100).toFixed(2);
}

/** A person's cap: the one in force on the date of their latest claim that counts (none: the sheet's today); '': none. */
function personCap(claims: Claim[], holds: Hold[], rules: DueRules): string {
  const latest = claims.filter((c) => counts(c, holds, rules.today)).reduce((d, c) => (c.date > d ? c.date : d), '');
  return rules.capOn(latest || rules.today);
}

/** A person's cut total in whole hundredths (0 when not told who they are). */
const personCut = (rules: DueRules, shared?: Shared) => (shared ? hundredths(rules.cutOf(shared.personId)) : 0);

/**
 * A person's excess: by how much the figures of their claims that count are above the room the sheet's cap leaves them
 * (the cap less their cut total, not below 0.00) — what the cap takes off their due-total; 0.00 when they are not
 * (or the due-total is n/a).
 */
export function personExcess(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
  shared?: Shared,
): string {
  const sum = personSum(claims, rates, grades, holds, rules, shared);
  const cap = personCap(claims, holds, rules);
  if (sum === NA || cap === '') return '0.00';
  const room = Math.max(0, hundredths(cap) - personCut(rules, shared));
  return (Math.max(0, hundredths(sum) - room) / 100).toFixed(2);
}

/**
 * Who a person is among the sheet's claims and people, to part shared claims: given, a person's own shared claim counts
 * its due less its holders' parts, and each claim they hold a share of counts their part (see {@link sharedParts}).
 */
export type Shared = {
  personId: number;
  claims: Claim[];
  people: { id: number; grades: GradeFrom[]; holds: Hold[]; retiredFrom: string | null }[];
};

/**
 * A holder's part of a shared claim with the given due: once settled, frozen as its fixed due times their share divided
 * by 100, rounded half to even; else its amount times their share divided by 100, times the rate of the holder's own
 * grade in force on its date (of the rate versions that apply to it) divided by 100, rounded like the claim — n/a (counted
 * as 0.00) when that grade has no rate, or when the due is n/a.
 */
export function sharePart(
  claim: Claim,
  due: string,
  share: ClaimShare,
  people: Shared['people'],
  rates: Rate[],
  rules: DueRules,
): string {
  if (due === NA) return NA;
  if (claim.due !== null) return percentOf(hundredths(due), hundredths(share.share), 'half-even');
  const holder = people.find((p) => p.id === share.personId);
  const rate = holder && rateFor(ratesForClaim(rates, claim), gradeOn(holder.grades, claim.date), claim.date);
  if (rate === undefined) return NA;
  return partOf(hundredths(claim.amount), hundredths(share.share), hundredths(rate), roundingFor(claim, rules));
}

/** Cents times two percents in basis points / 10^8, rounded to two decimals as told; worked in BigInt so it is exact. */
function partOf(amountCents: number, shareBasisPoints: number, rateBasisPoints: number, rounding: Rounding): string {
  const product = BigInt(amountCents) * BigInt(shareBasisPoints) * BigInt(rateBasisPoints);
  const negative = product < 0n;
  const abs = negative ? -product : product;
  const whole = abs / 100000000n;
  const rest = abs - whole * 100000000n;
  const up = rest > 50000000n || (rest === 50000000n && (rounding === 'half-up' || whole % 2n === 1n));
  const cents = Number(whole + (up ? 1n : 0n)) * (negative ? -1 : 1);
  return (cents / 100).toFixed(2);
}

/** A claim's own person's part of its due: the due less its holders' parts (n/a taking nothing); n/a stays n/a. */
export function ownPart(claim: Claim, due: string, people: Shared['people'], rates: Rate[], rules: DueRules): string {
  if (due === NA || !claim.shares?.length) return due;
  const parts = total(claim.shares.map((s) => sharePart(claim, due, s, people, rates, rules)));
  return ((hundredths(due) - hundredths(parts)) / 100).toFixed(2);
}

/**
 * The parts of other people's claims a person holds shares of, each as the claim (counting for its own person) and the
 * holder's part (see {@link sharePart}; the claim's due worked out by its own person's grades).
 */
export function sharedParts(shared: Shared, rates: Rate[], rules: DueRules): { claim: Claim; part: string }[] {
  const parts: { claim: Claim; part: string }[] = [];
  for (const c of shared.claims) {
    const held = c.shares?.find((s) => s.personId === shared.personId);
    const owner = held && shared.people.find((p) => p.id === c.personId);
    if (!held || !owner || !counts(c, liveHolds(owner, rules.today), rules.today)) continue;
    parts.push({ claim: c, part: sharePart(c, claimDue(c, rates, owner.grades, rules), held, shared.people, rates, rules) });
  }
  return parts;
}

/** A person's due-total before the cap: their counting claims' figures added up (parted when shared), or n/a. */
function personSum(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
  shared?: Shared,
): string {
  const counted = claims.filter((c) => counts(c, holds, rules.today));
  const parts = shared ? sharedParts(shared, rates, rules) : [];
  const figures = [
    ...counted.map((c) => (shared ? ownPart(c, claimDue(c, rates, grades, rules), shared.people, rates, rules) : claimDue(c, rates, grades, rules))),
    ...parts.map((p) => p.part),
  ];
  const anyFigure = counted.some(keepsFigure) || parts.some((p) => keepsFigure(p.claim)) || figures.some((f) => f !== NA);
  if (rateFor(rates, gradeOn(grades, rules.today), rules.today) === undefined && !anyFigure) {
    return NA;
  }
