// A claim's due: the one fixed when it was settled, else the greater of the floor and its amount at the rate in force on its date for its person's grade (or its stated figure), plus any late charge on that floored figure while it is overdue.
export function ClaimDue({ claim, person }: { claim: Claim; person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  return <span data-testid="claim-due">{claimDue(claim, rates, person.grades, rules)}</span>;
}
import { useClaims } from '../claims/claims';
import { liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { personExcess, useRates } from './rates';
import { useColumnShown } from '../columns/columns';

// A person's excess: by how much the figures of their claims that count are above their cap (the one in force on the date of their latest claim that counts); 0.00 otherwise.
export function PersonExcess({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const all = useClaims().data ?? [];
  const people = usePeople().data ?? [];
  const claims = all.filter((c) => c.personId === person.id);
  const shared = { personId: person.id, claims: all, people };
  if (!useColumnShown('excess')) return null;
  return <td data-testid="person-excess">{personExcess(claims, rates, person.grades, liveHolds(person, rules.today), rules, shared)}</td>;
}

