import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn } from '../people/people';
import type { GradeFrom } from '../people/people';
import { cutTotal, personCuts, usePools } from '../pools/pools';
import type { Pool } from '../pools/pools';

/** A role given to a user name: clerk, steward, viewer (sees everything, changes nothing) or restricted (a clerk who sees on the
 * people list only the people of their crews and themselves). A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the terms set
 * for each grade that has its own (by grade; any other grade uses the sheet's terms), the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), the entry date (yyyy-MM-dd; '': off — a new claim left without a date takes it instead of the
 * sheet's today), the cap (two decimals; '': none — a person's due-total is at most it less their cut total, not below 0.00), the proof threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is settled or approved only once it has a proof), the note threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is opened only with a note), the review threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date goes to REVIEW when opened), and the roles
 * given to user names. The clerk limit, floor, terms, grade terms, late percent, cap, proof threshold, note threshold and review threshold are those in force on the sheet's
 * today; `history` holds every value recorded for them, by key (floor, late-pct, terms, terms-<grade>, grace-<grade>, clerk-limit, clerk-limit-<grade>,
 * cap, proof-threshold, proof-threshold-<grade>, note-threshold, review-threshold, rounding), oldest from-date first (value '': blank). `permissions` is the permission matrix: by action, the
 * roles allowed it, comma separated ('': blank, the standing rule); it is not dated.
 * `graceDays` is the grace days (whole days; '': off — when the sheet's today is changed, an open period whose
 * to-date plus them is before the new today is closed); it is not dated.
 * `escalateAfter` is the escalation gap (whole days; '': off — reminding a claim whose previous reminder was at least
 * that many days before the sheet's today escalates it, once per claim); it is not dated.
 * `reviewSla` is the review SLA (whole days; '': none — a REVIEW claim whose review day, the sheet's today when it went to
 * REVIEW, plus that many days is before the sheet's today is late); it is not dated.
 * `pendingSla` is the pending SLA (whole days; '': none — a PENDING claim whose pending day, the sheet's today when it last
 * went to PENDING, plus that many days is before the sheet's today is late); it is not dated.
 * `proofKinds` is the proof kinds, comma separated ('': none — while set, a claim whose due is above the proof threshold is
 * settled or approved only once it has a proof of each); it is not dated.
 * `defaultGrade` is the default grade ('': blank, A), the grade a quick-added person and an imported line with a blank grade
 * take; it is not dated.
 * `delegations` is the steward role delegated to user names, in the order made.
 * `scoreMid` and `scoreHigh` are the score thresholds (whole numbers; '': blank — while both are set, each person shows a
 * band); they are not dated.
 * `scoreLog` is the score log switch ('on'; '': blank — while on, changing the sheet's today records each person's score in
 * the audit); it is not dated.
 * `maxOpen` is the maximum of OPEN and PENDING claims per person (a whole number; '': none — opening a claim of a person
 * who already has that many is refused); it is not dated.
 * `alertThreshold` is the alert threshold ('': off); it is not dated.
 * `pot` is the pot ('': none), the pot of each pool that is a member of no pool, shared out among its members when it is balanced; it is not dated.
 * `parent` is the parent sheet's id ('': none), whose rates a grade with none of its own in force takes; it is not dated.
 * `fiscalStartMonth` is the month (1 to 12) each fiscal year starts in; it is not dated.
 * `rounding` is the rounding mode in force on the sheet's today (half-up or half-even; '': none — a claim with none in force on its
 * date rounds by the policy date); it is dated, its values in `history` under rounding.
 * `policyVersion` is the sheet's current policy version: every change to one of the policy settings (the rounding mode, the
 * floor, the cap, the terms, the late percent and the clerk limit) is a new version, numbered from 1 in the order made;
 * `policyVersions` holds them all, in that order.
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; gradeTerms: Record<string, number>; latePct: string; policyDate: string; periodNumberingFrom: string; entryDate: string; cap: string; proofThreshold: string; noteThreshold: string; reviewThreshold: string; roles: UserRole[]; history: Record<string, FromValue[]>; permissions: Record<string, string>; graceDays: string; delegations: Delegation[]; pot: string; parent: string; fiscalStartMonth: string; alertThreshold: string; rounding: string; escalateAfter: string; reviewSla: string; proofKinds: string; defaultGrade: string; scoreMid: string; scoreHigh: string; scoreLog: string; maxOpen: string; pendingSla: string; policyVersion: number; policyVersions: PolicyVersion[] };

/**
