/** How many days back from the sheet's today, today included, a claim keeps its person active. */
export const ACTIVE_DAYS = 30;

/** The first date (yyyy-MM-dd) of the active window ending on the sheet's today. */
const windowStart = (today: string) =>
  new Date(Date.parse(`${today}T00:00:00Z`) - (ACTIVE_DAYS - 1) * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether a person is active: they have an OPEN or PENDING claim that counts (not one a hold covers, nor a
 * deferred one) dated within the 30 days up to and including the sheet's today. `claims` are theirs.
 */
export function isActive(claims: Claim[], holds: Hold[], today: string): boolean {
  if (today === '') return false;
  const from = windowStart(today);
  return claims.some((c) => isOpen(c) && counts(c, holds, today) && c.date >= from && c.date <= today);
}
/**
 * A person's score: their settled figures (in cents) divided by 100, minus 5 for every overdue claim of theirs that
 * counts, rounded half to even to a whole number. Worked in whole cents so it is exact: (cents − 50000 × overdue) / 10000.
 */
export function score(settled: string, overdueCount: number): string {
  const value = Math.round(Number(settled) * 100) - 50000 * overdueCount;
  const whole = Math.floor(Math.abs(value) / 10000);
  const rest = Math.abs(value) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && whole % 2 === 1);
  const result = Math.sign(value) * (whole + (up ? 1 : 0));
  return String(result === 0 ? 0 : result);
}

/** A score's band: HIGH at or above the high threshold, MID at or above the mid one, else LOW; '' while either is blank. */
export function band(value: string, mid: string, high: string): string {
  if (mid === '' || high === '') return '';
  const n = Number(value);
  if (n >= Number(high)) return 'HIGH';
  if (n >= Number(mid)) return 'MID';
  return 'LOW';
}

